package obligation

import (
	"encoding/base64"
	"testing"
)

// Real, live-captured obligation account bytes (2026-09-07) -- the exact
// same accounts TestKnownWalletAddressesMatchRustDerivation pins the
// addresses of. Hardcoded here (rather than re-fetched over RPC) so this
// test is deterministic and offline; ground truth for both was
// cross-checked against the identical Python/Rust-offset decoding used
// live this session before this Go port existed.
const (
	hawkesSolendBase64      = ""
	directionalKaminoBase64 = ""
)

func TestParseSolendKnownDeposit(t *testing.T) {
	body, err := base64.StdEncoding.DecodeString(hawkesSolendBase64)
	if err != nil {
		t.Fatalf("decode fixture: %s", err)
	}
	parsed, err := ParseSolend(body)
	if err != nil {
		t.Fatalf("ParseSolend: %s", err)
	}
	if len(parsed.Deposits) != 1 {
		t.Fatalf("len(Deposits) = %d, want 1", len(parsed.Deposits))
	}
	if len(parsed.Borrows) != 0 {
		t.Fatalf("len(Borrows) = %d, want 0", len(parsed.Borrows))
	}
	wantReserve := "BgxfHJDzm44T7XG68MYKx7YisTjZu73tVovyZSjJMpmw"
	if got := parsed.Deposits[0].Reserve.String(); got != wantReserve {
		t.Errorf("Deposits[0].Reserve = %s, want %s", got, wantReserve)
	}
	if got := parsed.Deposits[0].Amount; got != 3729321 {
		t.Errorf("Deposits[0].Amount = %d, want 3729321", got)
	}
}

func TestParseKaminoKnownDeposit(t *testing.T) {
	body, err := base64.StdEncoding.DecodeString(directionalKaminoBase64)
	if err != nil {
		t.Fatalf("decode fixture: %s", err)
	}
	parsed, err := ParseKamino(body)
	if err != nil {
		t.Fatalf("ParseKamino: %s", err)
	}
	if len(parsed.Deposits) != 1 {
		t.Fatalf("len(Deposits) = %d, want 1", len(parsed.Deposits))
	}
	wantReserve := "D6q6wuQSrifJKZYpR1M8R4YawnLDtDsMmWM1NbBmgJ59"
	if got := parsed.Deposits[0].Reserve.String(); got != wantReserve {
		t.Errorf("Deposits[0].Reserve = %s, want %s", got, wantReserve)
	}
	if got := parsed.Deposits[0].Amount; got != 2982906 {
		t.Errorf("Deposits[0].Amount = %d, want 2982906", got)
	}
	t.Logf("real borrows found: %d", len(parsed.Borrows))
	for _, b := range parsed.Borrows {
		t.Logf("  borrow reserve=%s amount=%d", b.Reserve, b.Amount)
	}
}
